command:
python -c "from PIL import Image, ImageDraw; import os, glob, math; groups=[('delay','/home/jake/Developer/study/Continuous-Time-Signal-Processing/3. Time-Domain Signal Operations/3.1. Time Shifting/Source/3.1.1. Delaying a Signal/Images/*.png'),('ref','/home/jake/Developer/study/Completed/04 - Horizontal Translations of Functions - 1584/Source/Images/*.png')];
for name,pat in groups:
 files=sorted(glob.glob(pat)); thumbs=[]
 for f in files:
  im=Image.open(f).convert('RGB'); im.thumbnail((420,260)); canvas=Image.new('RGB',(460,320),'white'); canvas.paste(im,((460-im.width)//2,30)); d=ImageDraw.Draw(canvas); d.text((8,8),os.path.basename(f)[:54],fill=(0,0,0)); d.text((8,290),str(Image.open(f).size),fill=(80,80,80)); thumbs.append(canvas)
 cols=2 if name=='delay' else 4; rows=math.ceil(len(thumbs)/cols); sheet=Image.new('RGB',(cols*460,rows*320),(245,245,245))
 for i,t in enumerate(thumbs): sheet.paste(t,((i%cols)*460,(i//cols)*320))
 out=f'/tmp/{name}_lesson_contact.png'; sheet.save(out); print(out)"

